changeSet.sql:
create table webseite_aenderung (
    id bigserial constraint webseite_aenderung_pk primary key,
    xid xid8 not null,
    dokument_id uuid not null,
    zeit timestamptz not null default clock_timestamp(),
    status text,
    version int,
    stufe_vorher text constraint webseite_aenderung_vorher_ck
        check (stufe_vorher in ('oeffentlich', 'mitglieder', 'vorstand')),
    stufe_nachher text constraint webseite_aenderung_nachher_ck
        check (stufe_nachher in ('oeffentlich', 'mitglieder', 'vorstand')),
    fehlercode text
);
create index webseite_aenderung_xid_ix on webseite_aenderung (xid, id);
create index webseite_aenderung_zeit_ix on webseite_aenderung (zeit);

create table webseite_feed_stand (
    id int constraint webseite_feed_stand_pk primary key constraint webseite_feed_stand_ck check (id = 1),
    bereinigt_bis xid8
);
insert into webseite_feed_stand (id, bereinigt_bis) values (1, null);

create function webseite_aenderung_erfassen() returns trigger language plpgsql as $$
declare
    vorher text;
    nachher text;
    fehlercode text;
begin
    if TG_OP in ('UPDATE', 'DELETE') then
        vorher := case when OLD.status = 'ARCHIVIERT' and OLD.vertraulichkeit = 'NORMAL'
                and OLD.bestaetigt is not null and OLD.zusatz -> 'veroeffentlicht' = 'true'::jsonb
                and OLD.zusatz ->> 'zugriff' in ('oeffentlich', 'mitglieder', 'vorstand')
            then OLD.zusatz ->> 'zugriff' end;
    end if;
    if TG_OP = 'DELETE' then
        execute format('insert into %I.webseite_aenderung (xid, dokument_id, zeit, status, version, '
                || 'stufe_vorher, stufe_nachher, fehlercode) values (pg_current_xact_id(), $1, '
                || 'clock_timestamp(), null, null, $2, null, null)', TG_TABLE_SCHEMA)
            using OLD.id, vorher;
        return null;
    end if;
    nachher := case when NEW.status = 'ARCHIVIERT' and NEW.vertraulichkeit = 'NORMAL'
            and NEW.bestaetigt is not null and NEW.zusatz -> 'veroeffentlicht' = 'true'::jsonb
            and NEW.zusatz ->> 'zugriff' in ('oeffentlich', 'mitglieder', 'vorstand')
        then NEW.zusatz ->> 'zugriff' end;
    if TG_OP = 'UPDATE' and OLD.status is not distinct from NEW.status
            and OLD.version is not distinct from NEW.version
            and OLD.fehler is not distinct from NEW.fehler
            and vorher is not distinct from nachher then
        return null;
    end if;
    fehlercode := case NEW.status when 'FEHLER' then 'VERARBEITUNG_FEHLGESCHLAGEN'
        when 'ARCHIVIERUNG_FEHLER' then 'ARCHIVIERUNG_FEHLGESCHLAGEN' end;
    execute format('insert into %I.webseite_aenderung (xid, dokument_id, zeit, status, version, '
            || 'stufe_vorher, stufe_nachher, fehlercode) values (pg_current_xact_id(), $1, '
            || 'clock_timestamp(), $2, $3, $4, $5, $6)', TG_TABLE_SCHEMA)
        using NEW.id, NEW.status, NEW.version, vorher, nachher, fehlercode;
    return null;
end
$$;
create trigger webseite_aenderung_erfassen after insert or update or delete on dokument
    for each row execute function webseite_aenderung_erfassen()

rollback.sql:
drop trigger if exists webseite_aenderung_erfassen on dokument;
drop function if exists webseite_aenderung_erfassen();
drop table if exists webseite_feed_stand;
drop table if exists webseite_aenderung
